(function() {
    var loaded = false;
    function loadMenuImages() {
      if (loaded) return;
      loaded = true;
      var imgs = document.querySelectorAll('.menu-best-sellers-grid__item-image[data-src]');
      for (var i = 0; i < imgs.length; i++) {
        imgs[i].src = imgs[i].getAttribute('data-src');
        imgs[i].removeAttribute('data-src');
      }
    }
    var nav = document.querySelector('.header-menu.nav-wrapper');
    if (nav) {
      nav.addEventListener('mouseenter', loadMenuImages, { once: true });
      nav.addEventListener('touchstart', loadMenuImages, { once: true, passive: true });
    }
    /* Fallback: load after 5 seconds idle in case menu is opened via keyboard */
    if (typeof requestIdleCallback !== 'undefined') {
      requestIdleCallback(loadMenuImages, { timeout: 5000 });
    } else {
      setTimeout(loadMenuImages, 5000);
    }
  })();


